import{_ as e,o as s,c as n,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"launch 与 launch_ros 的分层架构关系","description":"","frontmatter":{},"headers":[],"relativePath":"0-收集箱/2 计算机/开发框架/ROS2/launch 与 launch_ros 的分层架构关系.md","filePath":"0-收集箱/2 计算机/开发框架/ROS2/launch 与 launch_ros 的分层架构关系.md","lastUpdated":1786948858000}'),c={name:"0-收集箱/2 计算机/开发框架/ROS2/launch 与 launch_ros 的分层架构关系.md"};function t(l,a,d,i,r,h){return s(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="launch-与-launch-ros-的分层架构关系" tabindex="-1"><code>launch</code> 与 <code>launch_ros</code> 的分层架构关系 <a class="header-anchor" href="#launch-与-launch-ros-的分层架构关系" aria-label="Permalink to &quot;`launch` 与 `launch_ros` 的分层架构关系&quot;">​</a></h1> <h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2> <p><code>launch</code> 与 <code>launch_ros</code> 构成了 ROS 2 中启动系统（launch system）的两个核心层级：</p> <ul><li><strong><code>launch</code></strong> 是一个与 ROS 无关的通用进程编排框架；</li> <li><strong><code>launch_ros</code></strong> 是在 <code>launch</code> 基础上构建的 ROS 2 专用扩展层，用于管理 ROS 节点及相关资源。</li></ul> <p>二者采用清晰的分层设计，确保了核心框架的通用性与 ROS 功能的可扩展性。</p> <hr> <h2 id="_2-launch-通用启动框架" tabindex="-1">2. <code>launch</code>：通用启动框架 <a class="header-anchor" href="#_2-launch-通用启动框架" aria-label="Permalink to &quot;2. `launch`：通用启动框架&quot;">​</a></h2> <h3 id="_2-1-仓库结构" tabindex="-1">2.1 仓库结构 <a class="header-anchor" href="#_2-1-仓库结构" aria-label="Permalink to &quot;2.1 仓库结构&quot;">​</a></h3> <p>位于 <code>src/ros2/launch/</code>，包含以下子包：</p> <table tabindex="0"><thead><tr><th>子包</th> <th>职责</th></tr></thead> <tbody><tr><td><code>launch</code></td> <td>核心框架实现，完全独立于 ROS</td></tr> <tr><td><code>launch_xml</code></td> <td>支持通过 XML 文件定义 launch 描述</td></tr> <tr><td><code>launch_yaml</code></td> <td>支持通过 YAML 文件定义 launch 描述</td></tr> <tr><td><code>launch_testing</code></td> <td>提供通用的 launch 测试基础设施</td></tr></tbody></table> <h3 id="_2-2-核心抽象" tabindex="-1">2.2 核心抽象 <a class="header-anchor" href="#_2-2-核心抽象" aria-label="Permalink to &quot;2.2 核心抽象&quot;">​</a></h3> <ul><li><code>LaunchDescription</code>：描述一组待执行的动作。</li> <li><code>LaunchContext</code>：运行时上下文，用于传递状态和配置。</li> <li><code>LaunchService</code>：负责执行 <code>LaunchDescription</code>。</li> <li><code>Substitution</code>：支持在运行时动态替换字符串内容。</li> <li><code>Action</code>：表示一个可执行的操作单元。</li> <li><code>Condition</code>：控制动作是否执行的条件逻辑。</li></ul> <h3 id="_2-3-内置通用-actions" tabindex="-1">2.3 内置通用 Actions <a class="header-anchor" href="#_2-3-内置通用-actions" aria-label="Permalink to &quot;2.3 内置通用 Actions&quot;">​</a></h3> <p>这些动作不依赖 ROS，适用于任意进程管理场景：</p> <ul><li><code>ExecuteProcess</code>：启动任意外部进程；</li> <li><code>GroupAction</code>、<code>IncludeLaunchDescription</code>：组织和复用 launch 描述；</li> <li><code>SetEnvironmentVariable</code>、<code>TimerAction</code> 等：环境与时间控制操作。</li></ul> <hr> <h2 id="_3-launch-ros-ros-2-专用扩展层" tabindex="-1">3. <code>launch_ros</code>：ROS 2 专用扩展层 <a class="header-anchor" href="#_3-launch-ros-ros-2-专用扩展层" aria-label="Permalink to &quot;3. `launch_ros`：ROS 2 专用扩展层&quot;">​</a></h2> <h3 id="_3-1-依赖关系" tabindex="-1">3.1 依赖关系 <a class="header-anchor" href="#_3-1-依赖关系" aria-label="Permalink to &quot;3.1 依赖关系&quot;">​</a></h3> <p>位于 <code>src/ros2/launch_ros/</code>，其 <code>package.xml</code> 明确声明对 <code>launch</code> 和 <code>rclpy</code> 的依赖：</p> <div class="language-xml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">depend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;launch&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">depend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">depend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;rclpy&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">depend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-2-仓库结构" tabindex="-1">3.2 仓库结构 <a class="header-anchor" href="#_3-2-仓库结构" aria-label="Permalink to &quot;3.2 仓库结构&quot;">​</a></h3> <table tabindex="0"><thead><tr><th>子包</th> <th>职责</th></tr></thead> <tbody><tr><td><code>launch_ros</code></td> <td>提供 ROS 特有的 actions、substitutions 和事件处理</td></tr> <tr><td><code>ros2launch</code></td> <td>实现 <code>ros2 launch</code> 命令行工具</td></tr> <tr><td><code>launch_testing_ros</code></td> <td>为 ROS 节点测试提供扩展支持</td></tr></tbody></table> <h3 id="_3-3-新增的-ros-专用-actions" tabindex="-1">3.3 新增的 ROS 专用 Actions <a class="header-anchor" href="#_3-3-新增的-ros-专用-actions" aria-label="Permalink to &quot;3.3 新增的 ROS 专用 Actions&quot;">​</a></h3> <ul><li><code>Node</code>：启动标准 ROS 2 节点；</li> <li><code>LifecycleNode</code>：启动支持生命周期管理的节点；</li> <li><code>ComposableNodeContainer</code> / <code>LoadComposableNodes</code>：管理组件化节点容器及动态加载；</li> <li><code>PushRosNamespace</code>、<code>SetParameter</code>、<code>SetRemap</code>：分别用于设置命名空间、参数和话题/服务重映射。</li></ul> <hr> <h2 id="_4-设计意图与分层逻辑" tabindex="-1">4. 设计意图与分层逻辑 <a class="header-anchor" href="#_4-设计意图与分层逻辑" aria-label="Permalink to &quot;4. 设计意图与分层逻辑&quot;">​</a></h2> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>launch（平台无关核心）</span></span>\n<span class="line"><span>↑ 依赖 &amp; 扩展</span></span>\n<span class="line"><span>launch_ros（ROS 2 专用层）</span></span>\n<span class="line"><span>↑ 提供 CLI 接口</span></span>\n<span class="line"><span>ros2 launch（命令行入口）</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>解耦设计</strong>：<code>launch</code> 可在无 ROS 环境中独立使用，适用于通用进程编排任务；</li> <li><strong>功能聚焦</strong>：<code>launch_ros</code> 引入 <code>rclpy</code>、<code>lifecycle_msgs</code>、<code>composition_interfaces</code> 等 ROS 2 特有依赖，专注于节点生命周期、参数、命名空间等 ROS 概念的管理；</li> <li><strong>可测试性</strong>：两层均提供对应的测试框架（<code>launch_testing</code> 与 <code>launch_testing_ros</code>），支持单元测试与集成测试。</li></ul> <p>该架构体现了“核心通用、扩展专用”的软件工程原则，提升了系统的模块化程度与可维护性。</p>',55)])])}const _=e(c,[["render",t]]);export{p as __pageData,_ as default};
